using System.Security.Cryptography; using System.Text; using Marketplace.Domain.Common; namespace Marketplace.Domain.Delivery; public sealed class DeliveryCode:AggregateRoot<long>{private DeliveryCode(){}public long OrderId{get;private set;}public byte[] CodeHash{get;private set;}=null!;public DeliveryCodeStatus Status{get;private set;}public DateTime CreatedAtUtc{get;private set;}public DateTime? ExpiresAtUtc{get;private set;}public DateTime? UsedAtUtc{get;private set;}public static DeliveryCode Create(long id,long orderId,string raw,DateTime? expires){if(string.IsNullOrWhiteSpace(raw)||expires<=DateTime.UtcNow)throw new DomainException("Invalid delivery code.");return new(){Id=id,OrderId=orderId,CodeHash=Hash(raw),Status=DeliveryCodeStatus.Active,CreatedAtUtc=DateTime.UtcNow,ExpiresAtUtc=expires};}public bool Matches(string raw)=>Status==DeliveryCodeStatus.Active&&(ExpiresAtUtc==null||ExpiresAtUtc>DateTime.UtcNow)&&CryptographicOperations.FixedTimeEquals(CodeHash,Hash(raw));public void MarkUsed(){if(Status!=DeliveryCodeStatus.Active)throw new DomainException("Delivery code is not active.");Status=DeliveryCodeStatus.Used;UsedAtUtc=DateTime.UtcNow;}public void Expire(){if(Status!=DeliveryCodeStatus.Active)throw new DomainException("Delivery code is not active.");Status=DeliveryCodeStatus.Expired;}private static byte[] Hash(string v)=>SHA256.HashData(Encoding.UTF8.GetBytes(v.Trim()));}
